    """Helper to register a user and return the token."""
    payload = {"username": username, "password": password}
    if email:
        payload["email"] = email
    response = client.post(
        "/auth/register",
        data=json.dumps(payload),
        content_type="application/json"
    )
    data = json.loads(response.data)
